using System.Collections.Frozen;

namespace YDKE_Windows;

/// <summary>
/// UI-independent, explicit translations. Columns are key | en | tr | de | fr | es | pt | nl.
/// Add every language together: malformed, blank or duplicate resources fail validation.
/// Unknown keys retain the caller's English/Turkish text while MissingKeys can audit new call sites.
/// </summary>
internal static class ExperienceStrings
{
    private static readonly FrozenDictionary<string, FrozenDictionary<string, string>> Resources = Build();

    public static IReadOnlyList<string> Keys { get; } = Array.AsReadOnly(Resources["en"].Keys.Order(StringComparer.Ordinal).ToArray());

    public static string Get(string language, string key, string english, string turkish)
    {
        ArgumentNullException.ThrowIfNull(key);
        var code = LanguageCode(language);
        if (Resources.TryGetValue(code, out var strings) && strings.TryGetValue(key, out var text)) return text;
        if (Resources["en"].TryGetValue(key, out var fallback)) return fallback;
        return code == "tr" && !string.IsNullOrWhiteSpace(turkish) ? turkish
            : !string.IsNullOrWhiteSpace(english) ? english : key;
    }

    /// <summary>Descriptions are keyed by stable game ID, never by English display title.</summary>
    public static string GameDescription(string language, GameDefinition game)
    {
        ArgumentNullException.ThrowIfNull(game);
        return Get(language, $"GameDescription.{game.Id}", game.DescriptionEn, game.DescriptionTr);
    }

    /// <summary>Uses the same instruction keys as the native game's instruction switch.</summary>
    public static string GameInstructions(string language, GameDefinition game)
    {
        ArgumentNullException.ThrowIfNull(game);
        var suffix = game.Id switch
        {
            "dictation" => "Dictation", "listeningchoice" => "ListeningChoice",
            "sentencescramble" => "Sentence", "clozetest" => "Cloze",
            "categorysprint" => "Category", "cluedetective" => "Clues",
            "scrabble" => "Rack", "crossword" => "Crossword", "wordclass" => "Class",
            "oddoneout" => "Odd", "bingo" => "Bingo", "matrix" => "Matrix",
            "wordmorph" => "Semantic", "readingcomprehension" => "Reading",
            "dailychallenge" => "Daily", "wordguess" => "Guess", "survival" => "Survival",
            "hangman" => "Hangman", "memory" => "Memory", "scramble" => "Scramble",
            "bossrush" => "Boss", "codycross" => "Cody", "truefalse" => "TrueFalse",
            "wordrace" => "Race", "speedround" => "Speed", _ => null,
        };
        return suffix is null ? GameDescription(language, game) : Get(language, $"Games.Instructions.{suffix}", "", "");
    }

    public static string SkillLabel(string language, string skill) => Get(language, $"Skill.{skill}", skill, skill);

    /// <summary>Audits explicit translations, not fallback results. Unsupported languages report all keys.</summary>
    public static IReadOnlyList<string> MissingKeys(string language) => MissingKeys(language, Keys);

    /// <summary>Pass keys extracted from current U/T calls to detect concurrent additions too.</summary>
    public static IReadOnlyList<string> MissingKeys(string language, IEnumerable<string> expectedKeys)
    {
        ArgumentNullException.ThrowIfNull(expectedKeys);
        Resources.TryGetValue(LanguageCode(language), out var strings);
        return Array.AsReadOnly(expectedKeys.Distinct(StringComparer.Ordinal)
            .Where(key => strings is null || !strings.TryGetValue(key, out var text) || string.IsNullOrWhiteSpace(text))
            .Order(StringComparer.Ordinal).ToArray());
    }

    private static string LanguageCode(string? language) =>
        (language ?? "").Trim().Replace('_', '-').Split('-')[0].ToLowerInvariant();

    private static FrozenDictionary<string, FrozenDictionary<string, string>> Build()
    {
        // Local variables + const data avoid partially initialized static dictionaries.
        string[] languages = ["en", "tr", "de", "fr", "es", "pt", "nl"];
        var tables = languages.ToDictionary(code => code, _ => new Dictionary<string, string>(StringComparer.Ordinal), StringComparer.Ordinal);
        foreach (var row in (CoreData + "\n" + StudyData + "\n" + GameData + "\n" + GameUiData + "\n" + GameInstructionData + "\n" + KidsData + "\n" + SharedUiData + "\n" + SharedGameData + "\n" + ShellUxData).Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var cells = row.Split('|', StringSplitOptions.TrimEntries);
            if (cells.Length != languages.Length + 1 || cells.Any(string.IsNullOrWhiteSpace))
                throw new InvalidOperationException($"Invalid localization row: {cells[0]}");
            for (var index = 0; index < languages.Length; index++)
                if (!tables[languages[index]].TryAdd(cells[0], cells[index + 1]))
                    throw new InvalidOperationException($"Duplicate localization key: {cells[0]}");
        }
        ApplyLocalOnlyOverrides(tables);
        return tables.ToFrozenDictionary(pair => pair.Key, pair => pair.Value.ToFrozenDictionary(StringComparer.Ordinal), StringComparer.Ordinal);
    }

    private static void ApplyLocalOnlyOverrides(Dictionary<string, Dictionary<string, string>> tables)
    {
        void Set(string key, params string[] values)
        {
            var languages = new[] { "en", "tr", "de", "fr", "es", "pt", "nl" };
            if (values.Length != languages.Length) throw new InvalidOperationException($"Override requires {languages.Length} values: {key}");
            for (var index = 0; index < languages.Length; index++) tables[languages[index]][key] = values[index];
        }

